import teamsData from "../playersData";

const clubLogos = teamsData.map((team) => team.clubLogo);

const [clubLogo] = clubLogos;

function Team({ team }) {
	const {
		teamName,
		points,
		wins,
		draws,
		losses,
		goalsFor,
		goalsAgainst,
		goalDifference,
	} = team;
	// console.log(teamName);
	return (
		<tr>
			<td className="team-name">
				<img src={require(clubLogo)} alt="" /> {teamName}
			</td>
			<td>{points}</td>
			<td>{wins}</td>
			<td>{draws}</td>
			<td>{losses}</td>
			<td>{goalsFor}</td>
			<td>{goalsAgainst}</td>
			<td>{goalDifference}</td>
		</tr>
	);
}

export default Team;
